it('registers through its service provider and merges its config', function () {
    TestApp::boot();
    expect(config('connectors.facebook-lead-ads.mode'))->toBe('auto');
    expect(config('connectors.facebook-lead-ads.credentials'))->toBeArray();
});

it('fakes lead_get and records it for assertSent', function () {
    TestApp::boot();
    FacebookLeadAds::fake();
    $config = [
        'leadId' => 'example-leadId',
    ];
    $result = FacebookLeadAds::call('lead_get', $config);

    expect($result->mode->value)->toBe('fake');
    FacebookLeadAds::assertSent('lead_get', fn (array $sent): bool => $sent == $config);
    FacebookLeadAds::assertNotSent('no_such_operation');
    FacebookLeadAds::assertSentCount(1);
});

it('refuses a forged leadgen delivery before the app sees it', function () {
    $app = TestApp::boot();
    $app['router']->facebookLeadAdsLeadgen('/hooks/facebook-lead-ads');
    $response = TestApp::dispatch($app, Request::create('/hooks/facebook-lead-ads', 'POST', server: ['CONTENT_TYPE' => 'application/json'], content: '{"forged":true}'));

    expect($response->getStatusCode())->toBe(401);
});
